def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A valid number is a perfect square whose square root has exactly two
    distinct prime factors.
    """
    import math

    limit = math.isqrt(a)
    smallest_prime = list(range(limit + 1))
    for p in range(2, math.isqrt(limit) + 1):
        if smallest_prime[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if smallest_prime[multiple] == multiple:
                    smallest_prime[multiple] = p

    for root in range(limit, 1, -1):
        value = root
        distinct = 0
        previous = 0
        while value > 1:
            prime = smallest_prime[value]
            if prime != previous:
                distinct += 1
                if distinct > 2:
                    break
                previous = prime
            value //= prime
        if distinct == 2:
            return root * root

    # The input constraint a >= 36 guarantees that 36 is encountered.
    return 36
